namespace PurpleStream;
sealed class PlayerView:UserControl {
 readonly Panel surface=new(){Dock=DockStyle.Fill,BackColor=Color.Black};readonly Label title=Ui.Label("Select a channel, movie or episode",34);readonly Label message=Ui.Label("Ready",28);readonly TrackBar seek=new(){Dock=DockStyle.Fill,Minimum=0,Maximum=1000,TickStyle=TickStyle.None};readonly Label clock=new(){AutoSize=true,ForeColor=Ui.Muted,Padding=new(4,5,4,0)};
 readonly System.Windows.Forms.Timer timer=new(){Interval=250};readonly Button pause,back,forward;readonly ComboBox speed=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=70};bool dragging,muted;Form? fullscreen;Control? originalParent;DateTime connecting;public AsyncPlayback Engine{get;}public Channel? Media{get;private set;}public event Action<Channel>? RecordRequested;public event Action<Channel>? DownloadRequested;
 public PlayerView(){Dock=DockStyle.Fill;BackColor=Ui.Background;ForeColor=Ui.Text;Engine=new AsyncPlayback(IntPtr.Zero);surface.HandleCreated+=(_,_)=>Engine.Handle(surface.Handle);surface.DoubleClick+=(_,_)=>Fullscreen();Controls.Add(surface);Controls.Add(message);Controls.Add(title);
 var bottom=new TableLayoutPanel{Dock=DockStyle.Bottom,Height=155,BackColor=Ui.Surface,RowCount=2,ColumnCount=1};bottom.RowStyles.Add(new(SizeType.Absolute,34));bottom.RowStyles.Add(new(SizeType.Percent,100));Controls.Add(bottom);var timeline=new TableLayoutPanel{Dock=DockStyle.Fill,Height=34,ColumnCount=2};timeline.ColumnStyles.Add(new(SizeType.Percent,100));timeline.ColumnStyles.Add(new(SizeType.Absolute,115));timeline.Controls.Add(seek);timeline.Controls.Add(clock);bottom.Controls.Add(timeline,0,0);
 var row=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new(3),WrapContents=true};bottom.Controls.Add(row,0,1);
 back=Ui.Button("−10s",()=>Skip(-10000));pause=Ui.Button("Play / Pause",()=>{if(Engine.State.State is 0 or 5 or 6 or 7){if(Media!=null)Begin(Media);}else Engine.Pause();});forward=Ui.Button("+10s",()=>Skip(10000));row.Controls.AddRange(new Control[]{back,pause,forward,Ui.Button("Stop",()=>Stop()),Ui.Button("Full screen",Fullscreen)});
 var volume=new TrackBar{Minimum=0,Maximum=100,Value=80,Width=85,TickStyle=TickStyle.None};volume.ValueChanged+=(_,_)=>Engine.Volume(volume.Value);row.Controls.Add(Ui.Button("Mute",()=>{muted=!muted;Engine.Mute(muted);}));row.Controls.Add(volume);speed.Items.AddRange(new object[]{"0.5×","1×","1.25×","1.5×","2×"});speed.SelectedIndex=1;speed.SelectedIndexChanged+=(_,_)=>Engine.Rate(new[]{.5f,1f,1.25f,1.5f,2f}[speed.SelectedIndex]);row.Controls.Add(speed);row.Controls.Add(Ui.Button("Audio",()=>_ = Tracks(false)));row.Controls.Add(Ui.Button("Subtitles",()=>_ = Tracks(true)));row.Controls.Add(Ui.Button("Download",()=>{if(Media!=null)DownloadRequested?.Invoke(Media);}));row.Controls.Add(Ui.Button("Record live",()=>{if(Media!=null)RecordRequested?.Invoke(Media);}));row.Controls.Add(Ui.Button("Snapshot",Snapshot));
 seek.MouseDown+=(_,_)=>dragging=true;seek.MouseUp+=(_,_)=>{dragging=false;if(Engine.State.Seekable)Engine.Seek(Engine.State.Length*seek.Value/1000);};timer.Tick+=(_,_)=>Tick();timer.Start();Disposed+=(_,_)=>{timer.Dispose();Engine.Dispose();};}
 public void Begin(Channel media,long resume=0,int volume=80){Media=media;title.Text=media.Name;connecting=DateTime.UtcNow;message.Text="Connecting… You can continue browsing.";Engine.Handle(surface.Handle);Engine.Play(media.Url,volume,resume);}
 void Tick(){var s=Engine.State;message.Text=s.State is 1 or 2?$"{s.Message} ({(DateTime.UtcNow-connecting).TotalSeconds:0}s) — menu and Stop remain available":s.Message;clock.Text=$"{Ui.Clock(s.Time)} / {(s.Length>0?Ui.Clock(s.Length):"LIVE")}";seek.Enabled=s.Seekable&&s.Length>0;back.Enabled=forward.Enabled=s.Seekable;if(!dragging&&s.Length>0)seek.Value=(int)Math.Clamp(s.Time*1000/s.Length,0,1000);}
 public void Skip(long ms){if(Engine.State.Seekable)Engine.Skip(ms);else message.Text="Seeking is not available on this stream. Use Catch-up for archived programmes.";}
 public void Stop()=>Engine.Stop();
 public void TogglePause()=>Engine.Pause();
 public void Fullscreen(){if(fullscreen!=null){fullscreen.Close();return;}var owner=FindForm();originalParent=Parent;if(originalParent==null)return;originalParent.Controls.Remove(this);var f=new Form{FormBorderStyle=FormBorderStyle.None,WindowState=FormWindowState.Maximized,BackColor=Color.Black,KeyPreview=true};fullscreen=f;f.Controls.Add(this);f.KeyDown+=(_,e)=>{if(e.KeyCode==Keys.Escape||e.KeyCode==Keys.F)f.Close();else if(e.KeyCode==Keys.Space)TogglePause();else if(e.KeyCode==Keys.Left)Skip(-10000);else if(e.KeyCode==Keys.Right)Skip(10000);};f.FormClosing+=(_,_)=>{f.Controls.Remove(this);if(originalParent!=null&&!originalParent.IsDisposed)originalParent.Controls.Add(this);fullscreen=null;Engine.Handle(surface.Handle);};f.Show(owner);Engine.Handle(surface.Handle);}
 async Task Tracks(bool sub){try{var tracks=await Engine.Tracks(sub);if(IsDisposed)return;var menu=new ContextMenuStrip();if(tracks.Count==0)menu.Items.Add("No tracks available").Enabled=false;foreach(var t in tracks)menu.Items.Add(t.Name,null,(_,_)=>Engine.SelectTrack(sub,t.Id));menu.Show(this,10,Height-100);}catch{message.Text="Tracks are not available while the stream is connecting.";}}
 void Snapshot(){using var dialog=new SaveFileDialog{Filter="PNG image|*.png",FileName="Snapshot "+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".png"};if(dialog.ShowDialog(this)==DialogResult.OK)Engine.Snapshot(dialog.FileName);}
}


